test('R8: palestra exige exatamente 1 encontro e minicurso de 2 a 5; violacao da 422 QUANTIDADE_DE_ENCONTROS', async () => {
  const servidor = await subirServidor();
  try {
    await fetch(`${servidor.base}/_teste/reset`, { method: 'POST' });

    const violacoes = [
